class RenameImport(object):
    RENAMER = True

    def __init__(self, old_to_new):
        self.old_to_new = old_to_new
        both = set(old_to_new.keys()) & set(old_to_new.values())
        self.new_to_old = dict((new, old) for old, new in old_to_new.items())
        return

    def find_module(self, fullname, path=None):
        new_base_names = set([s.split(b'.')[0] for s in self.new_to_old])
        if fullname in new_base_names:
            return self
        else:
            return

    def load_module(self, name):
        path = None
        if name in sys.modules:
            return sys.modules[name]
        else:
            if name in self.new_to_old:
                oldname = self.new_to_old[name]
                module = self._find_and_load_module(oldname)
            else:
                module = self._find_and_load_module(name)
            sys.modules[name] = module
            return module

    def _find_and_load_module(self, name, path=None):
        bits = name.split(b'.')
        while len(bits) > 1:
            packagename = bits.pop(0)
            package = self._find_and_load_module(packagename, path)
            try:
                path = package.__path__
            except AttributeError:
                flog.debug((b'Package {0} has no __path__.').format(package))
                if name in sys.modules:
                    return sys.modules[name]
                flog.debug(b'What to do here?')

        name = bits[0]
        module_info = imp.find_module(name, path)
        return imp.load_module(name, *module_info)


class hooks(object):

    def __enter__(self):
        self.old_sys_modules = copy.copy(sys.modules)
        self.hooks_were_installed = detect_hooks()
        install_hooks()
        return self

    def __exit__(self, *args):
        if not self.hooks_were_installed:
            remove_hooks()
        return


if PY2:
    pass

def is_py2_stdlib_module(m):
    if PY3:
        return False
    if b'stdlib_path' not in is_py2_stdlib_module.__dict__:
        stdlib_files = [
         contextlib.__file__, os.__file__, copy.__file__]
        stdlib_paths = [os.path.split(f)[0] for f in stdlib_files]
        if not len(set(stdlib_paths)) == 1:
            flog.warn(b'Multiple locations found for the Python standard library: %s' % stdlib_paths)
        is_py2_stdlib_module.stdlib_path = stdlib_paths[0]
    if m.__name__ in sys.builtin_module_names:
        return True
    if hasattr(m, b'__file__'):
        modpath = os.path.split(m.__file__)
        if modpath[0].startswith(is_py2_stdlib_module.stdlib_path) and b'site-packages' not in modpath[0]:
            return True
    return False


def scrub_py2_sys_modules():
    if PY3:
        return {}
    scrubbed = {}
    for modulename in REPLACED_MODULES & set(RENAMES.keys()):
        if modulename not in sys.modules:
            continue
        module = sys.modules[modulename]
        if is_py2_stdlib_module(module):
            flog.debug((b'Deleting (Py2) {} from sys.modules').format(modulename))
            scrubbed[modulename] = sys.modules[modulename]
            del sys.modules[modulename]

    return scrubbed


def scrub_future_sys_modules():
    return {}


class suspend_hooks(object):

    def __enter__(self):
        self.hooks_were_installed = detect_hooks()
        remove_hooks()
        return self

    def __exit__(self, *args):
        if self.hooks_were_installed:
            install_hooks()
        return


def restore_sys_modules(scrubbed):
    clash = set(sys.modules) & set(scrubbed)
    if len(clash) != 0:
        first = list(clash)[0]
        raise ImportError((b'future module {} clashes with Py2 module').format(first))
    sys.modules.update(scrubbed)
    return


def install_aliases():
    if PY3:
        return
    for newmodname, newobjname, oldmodname, oldobjname in MOVES:
        __import__(newmodname)
        newmod = sys.modules[newmodname]
        __import__(oldmodname)
        oldmod = sys.modules[oldmodname]
        obj = getattr(oldmod, oldobjname)
        setattr(newmod, newobjname, obj)

    import urllib
    from future.backports.urllib import request
    from future.backports.urllib import response
    from future.backports.urllib import parse
    from future.backports.urllib import error
    from future.backports.urllib import robotparser
    urllib.request = request
    urllib.response = response
    urllib.parse = parse
    urllib.error = error
    urllib.robotparser = robotparser
    sys.modules[b'urllib.request'] = request
    sys.modules[b'urllib.response'] = response
    sys.modules[b'urllib.parse'] = parse
    sys.modules[b'urllib.error'] = error
    sys.modules[b'urllib.robotparser'] = robotparser
    try:
        import test
    except ImportError:
        pass

    try:
        from future.moves.test import support
    except ImportError:
        pass
    else:
        test.support = support
        sys.modules[b'test.support'] = support

    try:
        import dbm
    except ImportError:
        pass
    else:
        from future.moves.dbm import dumb
        dbm.dumb = dumb
        sys.modules[b'dbm.dumb'] = dumb
        try:
            from future.moves.dbm import gnu
        except ImportError:
            pass
        else:
            dbm.gnu = gnu
            sys.modules[b'dbm.gnu'] = gnu

        try:
            from future.moves.dbm import ndbm
        except ImportError:
            pass
        else:
            dbm.ndbm = ndbm
            sys.modules[b'dbm.ndbm'] = ndbm

    return


def install_hooks():
    if PY3:
        return
    install_aliases()
    flog.debug((b'sys.meta_path was: {0}').format(sys.meta_path))
    flog.debug(b'Installing hooks ...')
    newhook = RenameImport(RENAMES)
    if not detect_hooks():
        sys.meta_path.append(newhook)
    flog.debug((b'sys.meta_path is now: {0}').format(sys.meta_path))
    return


def enable_hooks():
    install_hooks()
    return


def remove_hooks(scrub_sys_modules=False):
    if PY3:
        return
    flog.debug(b'Uninstalling hooks ...')
    for i, hook in list(enumerate(sys.meta_path))[::-1]:
        if hasattr(hook, b'RENAMER'):
            del sys.meta_path[i]

    if scrub_sys_modules:
        scrub_future_sys_modules()
    return


def disable_hooks():
    remove_hooks()
    return


def detect_hooks():
    flog.debug(b'Detecting hooks ...')
    present = any([hasattr(hook, b'RENAMER') for hook in sys.meta_path])
    if present:
        flog.debug(b'Detected.')
    else:
        flog.debug(b'Not detected.')
    return present


if not hasattr(sys, b'py2_modules'):
    sys.py2_modules = {}

def cache_py2_modules():
    if len(sys.py2_modules) != 0:
        return
    import urllib
    sys.py2_modules[b'urllib'] = urllib
    import email
    sys.py2_modules[b'email'] = email
    import pickle
    sys.py2_modules[b'pickle'] = pickle
    return


def import_(module_name, backport=False):
    import importlib
    if PY3:
        return __import__(module_name)
    else:
        if backport:
            prefix = b'future.backports'
        else:
            prefix = b'future.moves'
        parts = prefix.split(b'.') + module_name.split(b'.')
        modules = []
        for i, part in enumerate(parts):
            sofar = (b'.').join(parts[:i + 1])
            modules.append(importlib.import_module(sofar))

        for i, part in reversed(list(enumerate(parts))):
            if i == 0:
                break
            setattr(modules[i - 1], part, modules[i])

        return modules[2]

    return


def from_import(module_name, *symbol_names, **kwargs):
    if PY3:
        return __import__(module_name)
    else:
        if b'backport' in kwargs and bool(kwargs[b'backport']):
            prefix = b'future.backports'
        else:
            prefix = b'future.moves'
        parts = prefix.split(b'.') + module_name.split(b'.')
        module = importlib.import_module(prefix + b'.' + module_name)
        output = [getattr(module, name) for name in symbol_names]
        if len(output) == 1:
            return output[0]
        return output

    return


class exclude_local_folder_imports(object):

    def __init__(self, *args):
        self.module_names = args
        if any([b'.' in m for m in self.module_names]):
            raise NotImplementedError(b'Dotted module names are not supported')
        return

    def __enter__(self):
        self.old_sys_path = copy.copy(sys.path)
        self.old_sys_modules = copy.copy(sys.modules)
        if sys.version_info[0] < 3:
            return
        FUTURE_SOURCE_SUBFOLDERS = [
         3, 4, 5, 6, 7]
        for folder in self.old_sys_path:
            if all([os.path.exists(os.path.join(folder, subfolder)) for subfolder in FUTURE_SOURCE_SUBFOLDERS]):
                sys.path.remove(folder)

        for m in self.module_names:
            try:
                module = __import__(m, level=0)
            except ImportError:
                pass

        return

    def __exit__(self, *args):
        sys.path = self.old_sys_path
        for m in set(self.old_sys_modules.keys()) - set(sys.modules.keys()):
            sys.modules[m] = self.old_sys_modules[m]

        return


